9	} from "./schemas/facts";
10	import { baseDocFields, zodObjectId } from "./schemas/shared";
11	
12	// The always-loadable tier: a budgeted per-anchor summary materialized from
13	// currently valid facts, cheap enough to inject into any agent context or
14	// UI header, while the full fact set stays behind search. Deterministic
15	// composition — no LLM call — so a refresh is safe to run on every change.
16	
17	export const dossierAnchorKinds = [
18	  "engagement",
19	  "organization",
20	  "person",
21	] as const;
22	
23	export const dossierSchema = z.object({
24	  ...baseDocFields,
25	  anchor: z.object({
26	    id: zodObjectId,
27	    kind: z.enum(dossierAnchorKinds),
28	  }),
29	  content: z.string(),
30	  factCount: z.number().int().min(0),
31	});
32	export type Dossier = z.infer<typeof dossierSchema>;
33	
34	export interface DossierAnchor {
35	  id: ObjectId;
36	  kind: (typeof dossierAnchorKinds)[number];
37	}
38	
39	const DEFAULT_BUDGET_TOKENS = 600;
40	/** chars-per-token heuristic; content is prose, so 4 is conservative. */
41	const CHARS_PER_TOKEN = 4;
42	
43	export const composeDossier = (
44	  anchorName: string,
45	  facts: Fact[],
46	  { budgetTokens = DEFAULT_BUDGET_TOKENS }: { budgetTokens?: number } = {}
47	): string => {
48	  const budgetChars = budgetTokens * CHARS_PER_TOKEN;
49	  const header = `# ${anchorName}\n`;
50	
51	  // Newest first: when the budget runs out, it is the oldest facts that drop.
52	  const byRecency = [...facts].sort(
53	    (a, b) => b.updatedAt.getTime() - a.updatedAt.getTime()
54	  );
55	
56	  let used = header.length;
57	  const kept: Fact[] = [];
58	  for (const fact of byRecency) {
59	    const line = `- ${fact.text}\n`;
60	    if (used + line.length > budgetChars) {
