  db: Db,
  tenantId: string,
  { generate, resolveAudioUrl, sourceId, transcribe }: ProcessSourceOptions
): Promise<ProcessSourceResult> => {
  const { sources } = getCollections(db);
  const source = await sources.findOne({ _id: sourceId, tenantId });
