// biome-ignore-all assist/source/useSortedKeys: MongoDB compound-index key order is semantically significant (tenantId must lead)

import type { Collection, Db } from "mongodb";
import type { Dossier } from "./dossier";
import type { Engagement, Organization, Person } from "./schemas/entities";
import type { Fact } from "./schemas/facts";
import type { Proposal } from "./schemas/proposals";
import type { Source } from "./schemas/sources";
import type { Usage } from "./schemas/usage";

export interface KnowledgeCollections {
  dossiers: Collection<Dossier>;
  engagements: Collection<Engagement>;
  facts: Collection<Fact>;
  organizations: Collection<Organization>;
  people: Collection<Person>;
  proposals: Collection<Proposal>;
  sources: Collection<Source>;
  usage: Collection<Usage>;
}

export const getCollections = (db: Db): KnowledgeCollections => ({
  dossiers: db.collection<Dossier>("dossiers"),
  engagements: db.collection<Engagement>("engagements"),
  facts: db.collection<Fact>("facts"),
  organizations: db.collection<Organization>("organizations"),
  people: db.collection<Person>("people"),
  proposals: db.collection<Proposal>("proposals"),
  sources: db.collection<Source>("sources"),
  usage: db.collection<Usage>("usage"),
});

export const ensureIndexes = async (db: Db): Promise<void> => {
  const {
    organizations,
    people,
    engagements,
    sources,
    proposals,
    facts,
    dossiers,
    usage,
  } = getCollections(db);

  await Promise.all([
    dossiers.createIndexes([
      {
        key: { tenantId: 1, "anchor.kind": 1, "anchor.id": 1 },
        name: "tenant_anchor",
        unique: true,
      },
      // listBriefs sorts a tenant's dossiers by recency; the unique
      // index above leads with anchor.kind and cannot serve that sort.
      { key: { tenantId: 1, updatedAt: -1 }, name: "tenant_recency" },
    ]),
    organizations.createIndexes([
      { key: { tenantId: 1, name: 1 }, name: "tenant_name" },
      { key: { tenantId: 1, domains: 1 }, name: "tenant_domains" },
    ]),
    people.createIndexes([
      { key: { tenantId: 1, organizationId: 1 }, name: "tenant_org" },
      { key: { tenantId: 1, emails: 1 }, name: "tenant_emails" },
    ]),
    engagements.createIndexes([
      { key: { tenantId: 1, organizationId: 1 }, name: "tenant_org" },
    ]),
    sources.createIndexes([
      {
        key: { tenantId: 1, status: 1, createdAt: -1 },
        name: "tenant_status_recency",
      },
      {
        key: { tenantId: 1, "email.messageId": 1 },
        name: "tenant_message",
        partialFilterExpression: { "email.messageId": { $exists: true } },
        unique: true,
      },
    ]),
    proposals.createIndexes([
      {
        key: { tenantId: 1, status: 1, createdAt: -1 },
        name: "tenant_status_recency",
      },
    ]),
    facts.createIndexes([
      {
        key: { tenantId: 1, "anchors.organizationId": 1 },
        name: "tenant_org_anchor",
      },
      {
        key: { tenantId: 1, "anchors.personId": 1 },
        name: "tenant_person_anchor",
      },
      {
        key: { tenantId: 1, "anchors.engagementId": 1 },
        name: "tenant_engagement_anchor",
      },
      { key: { tenantId: 1, sourceId: 1 }, name: "tenant_source" },
    ]),
    usage.createIndexes([
      { key: { tenantId: 1, createdAt: -1 }, name: "tenant_recency" },
      {
        key: { tenantId: 1, operation: 1, createdAt: -1 },
        name: "tenant_operation_recency",
      },
      // No TTL here, deliberately. Raw rows are kept indefinitely: this is
      // billing history, and the plan's original shape was a 90-day TTL plus
      // a monthly roll-up that would survive it — only the TTL got built.
      // Shipping that half was worse than shipping neither: at one tenant's
      // volume, even a busy year is on the order of 100k small documents,
      // which MongoDB does not notice, so unbounded growth here is a
      // non-problem. Silently deleting the only record of what a tenant cost
      // is a real one, and it is a one-way door — a TTL can always be added
      // later once a roll-up exists to hand off to, but there is no adding
      // back rows a TTL already expired. So: keep everything, add the
      // roll-up + TTL together when retention actually needs to bound this
      // collection's size.
    ]),
  ]);
};

import { z } from "zod";
import { rejectedDraftSchema } from "../extraction";
import { factCategoryValues } from "./facts";
import { baseDocFields, zodObjectId } from "./shared";

export const entityDraftSchema = z.object({
  // Loose by design: extractor output. Validated against the strict entity
  // schemas at confirmation time, when the review queue materializes entities.
  data: z.record(z.string(), z.unknown()),
  draftId: z.string().min(1),
  entityType: z.enum(["organization", "person", "engagement"]),
  resolution: z
    .object({
      createdEntityId: zodObjectId.optional(),
      status: z.enum(["pending", "confirmed", "discarded"]),
    })
    .default({ status: "pending" }),
});
export type EntityDraft = z.infer<typeof entityDraftSchema>;

export const factDraftAnchorsSchema = z
  .object({
    engagementDraftId: z.string().optional(),
    engagementId: zodObjectId.optional(),
    organizationDraftId: z.string().optional(),
    organizationId: zodObjectId.optional(),
    personDraftId: z.string().optional(),
    personId: zodObjectId.optional(),
  })
  .refine((a) => Object.values(a).some(Boolean), {
    message:
      "A fact draft must anchor to an existing entity or a sibling draft",
  });

export const factDraftSchema = z.object({
  anchors: factDraftAnchorsSchema,
  category: z.enum(factCategoryValues),
  confidence: z.number().min(0).max(1),
  resolution: z
    .object({
      factId: zodObjectId.optional(),
      finalText: z.string().optional(),
      status: z.enum(["pending", "confirmed", "edited", "discarded"]),
    })
    .default({ status: "pending" }),
  // Facts this draft replaces on confirmation (they get supersededBy stamped).
  // Required for consolidation drafts — it doubles as their provenance.
  supersedes: z.array(zodObjectId).min(1).optional(),
  text: z.string().min(1),
});
export type FactDraft = z.infer<typeof factDraftSchema>;

export const proposalSchema = z.object({
  ...baseDocFields,
  entityDrafts: z.array(entityDraftSchema),
  // Which extraction pass produced this. 1 for the original. Absent on
  // consolidation and contradiction proposals, which have no generation.
  extractionGeneration: z.number().int().min(1).optional(),
  factDrafts: z.array(factDraftSchema),
  // Reviewer-supplied context for this pass, when a re-extraction asked for it.
  hint: z.string().min(1).optional(),
  // ingestion: drafts extracted from a source, provenance is that sourceId.
  // consolidation / contradiction: drafts derived from existing facts, which
  // they supersede — their provenance is derivedFrom, not a source.
  kind: z.enum(["ingestion", "consolidation", "contradiction"]),
  // Drafts the model produced that failed validation. Recorded rather than
  // dropped, so a reviewer can see what extraction could not use.
  rejectedDrafts: z.array(rejectedDraftSchema).optional(),
  resolvedAt: z.date().optional(),
  resolvedBy: z.string().optional(),
  // Present ⇒ extraction judged there was nothing worth recording; drafts are
  // empty. Absent on every ordinary proposal — listOpenProposals filters on
  // { $exists: false }.
  skipReason: z.string().min(1).optional(),
  sourceId: zodObjectId.optional(),
  status: z.enum(["open", "resolved", "superseded"]),
});
export type Proposal = z.infer<typeof proposalSchema>;

